import{_ as t,o as s,c as a,ao as i}from"./chunks/framework.ucUddl5u.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"start/install.md","filePath":"start/install.md","lastUpdated":null}'),o={name:"start/install.md"};function n(l,e,d,r,h,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="Installation" tabindex="-1">Installation <a class="header-anchor" href="#Installation" aria-label="Permalink to &quot;Installation {#Installation}&quot;">​</a></h1><p>There are three ways to install Ship of Tools. GitHub Releases ship prebuilt artifacts for Linux x86_64, Windows x86_64 and macOS aarch64, so the default path is <a href="/ship-of-tools/dev/start/install#install-release">from release artifacts</a>.</p><ul><li><p><strong>Agent-driven</strong> — start a Claude Code or Codex session on the target machine and tell it:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Install Ship of Tools: fetch https://raw.githubusercontent.com/kalidke/ship-of-tools/main/docs/INSTALL-AGENT.md and follow it.</span></span></code></pre></div><p>The agent checks the machine, confirms the release assets match the platform, falls back to the source path when they do not, and checks that the result answers before it reports success. The runbook it follows is <code>docs/INSTALL-AGENT.md</code> in this repo.</p></li><li><p><strong><a href="/ship-of-tools/dev/start/install#install-release">From release artifacts</a></strong> — prebuilt binaries via the <code>install.sh</code> installer. No Rust toolchain is needed.</p></li><li><p><strong><a href="/ship-of-tools/dev/start/install#install-source">From source</a></strong> — clone, build the Rust workspace, instantiate the Julia environments. This is the path for developing Ship of Tools; <a href="./setup">Per-machine setup</a> adds the config and launcher checklist.</p></li></ul><h2 id="install-release" tabindex="-1">From release artifacts (Linux/macOS) <a class="header-anchor" href="#install-release" aria-label="Permalink to &quot;From release artifacts (Linux/macOS) {#install-release}&quot;">​</a></h2><p><code>scripts/install.sh</code> downloads a GitHub Release, verifies its checksums, and sets everything up under <code>~/.local/share/sot</code> by default:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/kalidke/ship-of-tools/main/scripts/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --local</span></span></code></pre></div><p>The script fetched from <code>main</code> only resolves the latest release and runs that release&#39;s own <code>install.sh</code>, so what gets installed is always a tagged release.</p><p>With no role flag and an interactive terminal, the installer asks which role this machine should play. In <code>curl | bash</code> or other non-interactive runs, pass the role explicitly:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Flag</th><th style="text-align:right;">Role</th></tr></thead><tbody><tr><td style="text-align:right;"><code>--local</code></td><td style="text-align:right;">all-in-one: frontend and backend on this machine</td></tr><tr><td style="text-align:right;"><code>--backend &lt;ssh-alias&gt;</code></td><td style="text-align:right;">frontend here, backend on a remote host over SSH forwarding; the flag names where the <em>backend</em> lives</td></tr><tr><td style="text-align:right;"><code>--be-only</code></td><td style="text-align:right;">headless backend only (servers)</td></tr></tbody></table><p>Plus <code>--version vX.Y.Z</code> to pin a release (default: latest), <code>--prefix &lt;dir&gt;</code> to relocate the install, <code>--port &lt;n&gt;</code> for the frontend&#39;s local TCP port of the SSH forward (remote role only), <code>--no-service</code> on backend roles when a shared-home deployment should not get a persistent user systemd unit, <code>--hub &lt;ssh-alias&gt;</code> to copy the hub&#39;s <code>~/.config/sot/hosts.toml</code> to this machine first (for a machine that does not share the hub&#39;s home directory), and <code>--force-role-change</code> (see the next section).</p><p>If <code>~/.config/sot/hosts.toml</code> already names this host, that entry decides which parts are installed and enabled here, and a role flag on the command line is ignored.</p><p>The checkout under the prefix is part of the installed product: a <code>git clone --filter=blob:none</code> of the selected tag, so history is available but only that tag&#39;s files are downloaded. The runtime resources and the in-app manual resolve from it. For roles that run a backend on this machine (<code>--local</code> and <code>--be-only</code>), the installer instantiates the Julia environments inside the checkout (<code>julia/kernel</code>, <code>julia/repl</code>, <code>julia/pluto</code>). <code>--backend &lt;ssh-alias&gt;</code> is a frontend-only install and uses Julia locally only to install the agent skills; install the remote machine as a backend role. Julia runs the installer&#39;s comm step on every role, which is why it is needed here too; the skills and hooks it installs are inert unless a session runs on this machine.</p><p>Connection behaviour is role-specific:</p><ul><li><p><code>--local</code> runs frontend and backend on one machine over the backend user&#39;s per-user socket. There is no SSH-to-localhost requirement.</p></li><li><p><code>--backend &lt;ssh-alias&gt;</code> creates SSH local forwards to the remote user&#39;s per-user backend socket.</p></li><li><p><code>--be-only</code> installs the headless backend and, unless <code>--no-service</code>, runs it as the <code>systemd --user</code> unit <code>sotd.service</code>.</p></li></ul><h3 id="Re-running-on-a-machine-that-already-has-an-install" tabindex="-1">Re-running on a machine that already has an install <a class="header-anchor" href="#Re-running-on-a-machine-that-already-has-an-install" aria-label="Permalink to &quot;Re-running on a machine that already has an install {#Re-running-on-a-machine-that-already-has-an-install}&quot;">​</a></h3><p>A re-run is an upgrade. The installer refuses to overwrite files that belong to another install: the <code>sotd.service</code> unit, the <code>sot-launch</code> wrapper, the desktop entry and the macOS app. If one of these already exists under a different prefix (a source checkout, another <code>--prefix</code>, an earlier trial install), the installer stops before writing anything and names the file and its owner. <code>--force-role-change</code> overrides that. A file whose owner cannot be determined (an unrecognized <code>sot-launch</code> shape) is refused with no override; move it aside and re-run.</p><h2 id="install-footprint" tabindex="-1">What the installer changes <a class="header-anchor" href="#install-footprint" aria-label="Permalink to &quot;What the installer changes {#install-footprint}&quot;">​</a></h2><p>Everything below is written under your home directory, with one exception: on Linux backend roles the installer runs <code>loginctl enable-linger</code> for your user, a systemd setting kept outside your home (it continues without it if that call is refused). Nothing needs root. The default prefix is <code>~/.local/share/sot</code> (<code>--prefix</code> moves it). There is no uninstall script; <a href="/ship-of-tools/dev/start/install#install-uninstall">Uninstall</a> lists the commands to remove each item by hand.</p><p>Roles: <em>all</em> is every install; <em>backend</em> is <code>--local</code> and <code>--be-only</code>; <em>frontend</em> is <code>--local</code> and <code>--backend</code>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Path</th><th style="text-align:right;">What</th></tr></thead><tbody><tr><td style="text-align:right;"><code>~/.local/share/sot/bin/</code></td><td style="text-align:right;"><em>all</em> · <code>sot</code> (frontend), <code>sotd</code> (backend daemon), <code>sot-capsule</code> (session supervisor), <code>sot-apply</code> (update applier)</td></tr><tr><td style="text-align:right;"><code>~/.local/share/sot/repo/</code></td><td style="text-align:right;"><em>all</em> · the release checkout, one directory per version under <code>repo/versions/</code> (the current and previous one are kept); <code>repo/current</code> links to the installed one</td></tr><tr><td style="text-align:right;"><code>~/.local/share/sot/julia/current</code></td><td style="text-align:right;"><em>all</em> · a link to the same checkout</td></tr><tr><td style="text-align:right;"><code>~/.local/share/sot/updates/</code></td><td style="text-align:right;"><em>all</em> · staging area for downloaded updates</td></tr><tr><td style="text-align:right;"><code>~/.local/share/sot/install.json</code></td><td style="text-align:right;"><em>all</em> · install manifest: prefix, version, and which parts (daemon, frontend) were installed</td></tr><tr><td style="text-align:right;"><code>~/.config/sot/settings.toml</code></td><td style="text-align:right;"><em>all</em> · a one-line stub, written only if missing</td></tr><tr><td style="text-align:right;"><code>~/.config/sot/hosts.toml</code></td><td style="text-align:right;"><em>all</em> · written only with <code>--hub</code>, as a copy fetched from the hub; otherwise only read</td></tr><tr><td style="text-align:right;"><code>~/.juliaup/</code></td><td style="text-align:right;"><em>all</em> · Julia 1.12, installed with the juliaup installer, only if no Julia 1.12 or newer is on <code>PATH</code> (an existing juliaup gets the 1.12 channel added instead)</td></tr><tr><td style="text-align:right;">the first depot in <code>DEPOT_PATH</code> (usually <code>~/.julia</code>)</td><td style="text-align:right;"><em>backend</em> · packages for the kernel, REPL and Pluto environments</td></tr><tr><td style="text-align:right;"><code>~/.config/systemd/user/sotd.service</code></td><td style="text-align:right;"><em>backend, Linux, unless <code>--no-service</code></em> · the backend service, enabled and started; <code>loginctl enable-linger</code> is also run so it survives logout. The service sources <code>~/.bashrc</code> before it starts <code>sotd</code>, so the backend and its sessions inherit your shell profile&#39;s exports.</td></tr><tr><td style="text-align:right;"><code>~/.local/bin/sot-launch</code></td><td style="text-align:right;"><em>frontend</em> · the launcher wrapper</td></tr><tr><td style="text-align:right;"><code>~/.local/share/applications/ship-of-tools.desktop</code></td><td style="text-align:right;"><em>frontend, Linux</em> · the desktop entry</td></tr><tr><td style="text-align:right;"><code>~/.local/share/icons/hicolor/</code></td><td style="text-align:right;"><em>frontend, Linux</em> · the icon, <code>256x256/apps/ship-of-tools.png</code></td></tr><tr><td style="text-align:right;"><code>~/Applications/Ship of Tools.app</code></td><td style="text-align:right;"><em>frontend, macOS</em> · app bundle</td></tr></tbody></table><p>The installer then runs <code>ShipTools.update_comm()</code> from the checkout, which installs the agent integration:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Path</th><th style="text-align:right;">What</th></tr></thead><tbody><tr><td style="text-align:right;"><code>~/.sot-comm/</code></td><td style="text-align:right;">the session messaging scripts (<code>bin/</code>) and their runtime state</td></tr><tr><td style="text-align:right;"><code>~/.local/bin/</code></td><td style="text-align:right;"><code>ccb</code> (Claude Code launcher), <code>ccx</code> (Codex launcher), <code>sot-fe</code>, <code>show-result</code>, <code>sot-gh-auth</code></td></tr><tr><td style="text-align:right;"><code>~/.claude/skills/</code></td><td style="text-align:right;">the Claude Code skills: <code>julia-repl</code>, <code>show-result</code>, <code>sot-comm</code>, <code>sot-session-start</code>, <code>sot-status</code>, <code>sitrep</code>, <code>worktree</code>, <code>project-log</code>, <code>sot-install</code>, <code>sot-setup</code>, <code>sot-statusline-setup</code>, <code>sot-gh-auth</code></td></tr><tr><td style="text-align:right;"><code>~/.claude/settings.json</code></td><td style="text-align:right;">hook entries for <code>UserPromptSubmit</code>, <code>PreToolUse</code> (on <code>AskUserQuestion</code>), <code>PostToolUse</code>, <code>Stop</code> and <code>SessionStart</code> (on <code>compact</code> and <code>clear</code>), each calling a <code>comm-*.sh</code> script in <code>~/.sot-comm/bin</code>; merged in without removing existing hooks</td></tr><tr><td style="text-align:right;"><code>~/.codex/skills/</code></td><td style="text-align:right;">the Codex skills <code>sot-comm</code> and <code>sot-session-start</code></td></tr><tr><td style="text-align:right;"><code>~/.codex/AGENTS.md</code></td><td style="text-align:right;">installed only if no <code>AGENTS.md</code> is there</td></tr><tr><td style="text-align:right;"><code>~/.agents/plugins/sot-comm/</code>, <code>~/.agents/plugins/marketplace.json</code></td><td style="text-align:right;">the Codex work-state hook plugin; written whether or not Codex is installed, and registered with <code>codex plugin add sot-comm@sot-local</code> when it is</td></tr></tbody></table><p><code>~/.claude</code> and <code>~/.codex</code> follow <code>CLAUDE_CONFIG_DIR</code> and <code>CODEX_HOME</code> when those are set; <code>~/.sot-comm</code> follows <code>SOT_COMM_HOME</code>. The other paths do not move: <code>~/.local/bin</code>, <code>~/.agents/plugins</code> and everything in the first table are always written in your home directory. Setting those three variables is therefore not an isolated try-out; for that, install under a separate user account or in a virtual machine.</p><p>The hooks do nothing in an agent session that has not joined the Ship of Tools session registry. Each hook first looks the session up in the session registry (<code>~/.sot-comm/registry.json</code>) and exits without writing anything when it is not there, which is the case for a <code>claude</code> or <code>codex</code> you start yourself in a terminal. Setting <code>SOT_COMM_HOOKS=off</code> turns the Claude Code work-state hooks off entirely.</p><p>The skills are likewise available in a plain terminal <code>claude</code>, but their commands need a Ship of Tools session: <code>julia-repl</code> and <code>show-result</code> reach <code>sot-fe</code>, which has nothing to talk to outside one.</p><p>A skill directory with the same name as one of the skills above is overwritten: each shipped file replaces the file of the same name, and any other file in that directory is deleted. No backup is made. Every re-run of the installer, including each update, repeats this. The five skills without an <code>sot-</code> prefix are the likeliest to collide with one of your own: <code>julia-repl</code>, <code>show-result</code>, <code>sitrep</code>, <code>worktree</code> and <code>project-log</code>.</p><p>The installer itself edits no shell profile. If no Julia 1.12 or newer is found and juliaup is not installed, it runs the juliaup installer, which adds its <code>PATH</code> block to your shell startup files; <code>juliaup self uninstall</code> removes it.</p><h3 id="How-agent-sessions-are-launched" tabindex="-1">How agent sessions are launched <a class="header-anchor" href="#How-agent-sessions-are-launched" aria-label="Permalink to &quot;How agent sessions are launched {#How-agent-sessions-are-launched}&quot;">​</a></h3><p>Sessions you create in the window start their agent with these permission settings:</p><ul><li><p><strong>Claude Code</strong>: <code>claude --permission-mode auto</code>.</p></li><li><p><strong>Codex</strong>: <code>codex --dangerously-bypass-approvals-and-sandbox --dangerously-bypass-hook-trust</code>, through the <code>ccx</code> launcher, which also marks the session&#39;s directory as trusted in <code>~/.codex/config.toml</code>.</p></li></ul><p>Claude Code&#39;s auto mode is not a bypass. It runs without routine permission prompts, but a separate classifier model reviews each action before it runs and blocks anything that goes beyond your request, targets infrastructure it does not recognise, or looks driven by hostile content; your own <code>ask</code> rules still prompt. See Claude Code&#39;s <a href="https://code.claude.com/docs/en/permission-modes" target="_blank" rel="noreferrer">permission modes</a>. Codex has no equivalent reviewed mode here: its flags turn approvals and the sandbox off.</p><p>These flags are fixed: no setting or environment variable changes them. The Claude Code flags are built into the daemon, and the Codex flags are in the <code>ccx</code> script, which every update overwrites. Ship of Tools adds no permission layer of its own on top. A <code>claude</code> or <code>codex</code> you start yourself, outside Ship of Tools, uses whatever flags you give it. See <a href="./../guide/orchestrator">Agent sessions</a>.</p><h2 id="install-uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#install-uninstall" aria-label="Permalink to &quot;Uninstall {#install-uninstall}&quot;">​</a></h2><p>There is no uninstall script. To remove an install made with the default prefix, stop the service and delete what the installer wrote:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sotd.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/systemd/user/sotd.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon-reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">loginctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable-linger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # skip if something else needs linger</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/sot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/sot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.sot-comm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin/sot-launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin/ccb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin/ccx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin/sot-fe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      ~/.local/bin/show-result</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin/sot-gh-auth</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/applications/ship-of-tools.desktop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      ~/.local/share/icons/hicolor/256x256/apps/ship-of-tools.png</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/skills/{julia-repl,show-result,sot-comm,sot-session-start,sot-status,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sitrep,worktree,project-log,sot-install,sot-setup,sot-statusline-setup,sot-gh-auth}</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.codex/skills/{sot-comm,sot-session-start}</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.agents/plugins/sot-comm</span></span></code></pre></div><p>These commands use the default locations. If <code>CLAUDE_CONFIG_DIR</code>, <code>CODEX_HOME</code> or <code>SOT_COMM_HOME</code> is set, use those directories instead of <code>~/.claude</code>, <code>~/.codex</code> and <code>~/.sot-comm</code>. Deleting <code>~/.config/sot</code> also deletes your <code>hosts.toml</code> and any settings you edited; keep a copy if you want them.</p><p>Then, by hand:</p><ul><li><p>remove the hook entries that call <code>~/.sot-comm/bin/comm-*.sh</code> from <code>~/.claude/settings.json</code>;</p></li><li><p>if Codex is installed, remove the <code>sot-comm@sot-local</code> plugin (it is listed by <code>codex plugin list</code>);</p></li><li><p>remove the <code>sot-local</code> entry from <code>~/.agents/plugins/marketplace.json</code>, or delete the file if nothing else is listed in it;</p></li><li><p>remove the <code>[projects.&quot;&lt;dir&gt;&quot;]</code> blocks with <code>trust_level = &quot;trusted&quot;</code> that <code>ccx</code> appended to <code>~/.codex/config.toml</code>, one per directory a Codex session ran in;</p></li><li><p>delete <code>~/.codex/AGENTS.md</code> if the installer created it;</p></li><li><p>on macOS, delete <code>~/Applications/Ship of Tools.app</code>;</p></li><li><p><code>~/.juliaup</code> and the Julia depot are ordinary Julia installs; keep them or remove them with juliaup (<code>juliaup self uninstall</code> also removes the <code>PATH</code> block it added to your shell startup files).</p></li></ul><p>Sessions also keep runtime state under <code>~/.local/state</code> (or <code>$XDG_STATE_HOME</code>); see <a href="./../concepts/sessions">Sessions and persistence</a>.</p><h2 id="Updating" tabindex="-1">Updating <a class="header-anchor" href="#Updating" aria-label="Permalink to &quot;Updating {#Updating}&quot;">​</a></h2><p>Re-running the install command is also the updater. The built-in update check, pinning a version, and rolling back are in <a href="./../guide/updating">Updating and rollback</a>.</p><h2 id="Requirements" tabindex="-1">Requirements <a class="header-anchor" href="#Requirements" aria-label="Permalink to &quot;Requirements {#Requirements}&quot;">​</a></h2><h3 id="platforms" tabindex="-1">Platforms <a class="header-anchor" href="#platforms" aria-label="Permalink to &quot;Platforms {#platforms}&quot;">​</a></h3><ul><li><p><strong>Linux x86_64</strong>: all roles.</p></li><li><p><strong>Windows</strong>: frontend only, against a Linux backend.</p></li><li><p><strong>macOS (Apple Silicon)</strong>: experimental; the tested use is a frontend against a Linux backend (<code>--backend</code>) — the other roles install but agent sessions on a Mac backend are not supported yet.</p></li><li><p><strong>linux-x86_64</strong> or <strong>macos-aarch64</strong> release artifacts (a <strong>windows-x86_64</strong> zip also ships for the Windows frontend path below).</p></li><li><p><strong>git</strong>, <strong>curl</strong> and <strong>tar</strong>.</p></li><li><p>A <strong>coding agent</strong> (Claude Code or Codex), installed and logged in on every machine that runs sessions. The installer does not install one.</p></li><li><p><strong>Julia 1.12</strong> or newer. The installer installs it with juliaup when missing; an existing juliaup only gets the 1.12 channel added, not made the default, so if your default channel is older, run <code>juliaup default 1.12</code> yourself (or set <code>SOT_JULIA_BIN</code>).</p></li><li><p><strong>node/npm</strong>, optional, on the backend machine: typeset math in markdown previews renders in a long-lived node process, whose dependencies the installer fetches with <code>npm ci</code>. Without it the installer warns and continues, and math renders as raw LaTeX. To add math later, install node and re-run the installer (or <code>npm ci</code> in <code>&lt;checkout&gt;/rust/backend/sidecars/mathjax</code>).</p></li><li><p><strong>poppler-utils</strong> (<code>pdftoppm</code>, <code>pdfinfo</code>) and <strong>ffmpeg</strong>, optional, on the backend machine: PDF pages and video poster frames in previews. The installer does not check for them; without them the preview shows a note naming the missing tool.</p></li><li><p>Frontend roles need <strong>glibc 2.35</strong> or newer (Ubuntu 22.04 or newer) and a desktop session (X11 or Wayland): the frontend is a native window. It renders with <code>wgpu</code> through Vulkan on Linux, Metal on macOS and DirectX 12 or Vulkan on Windows, so a Linux frontend needs a working Vulkan driver. The backend binary is static musl and runs on any distribution; <code>--be-only</code> has no glibc floor.</p></li><li><p><code>--backend &lt;ssh-alias&gt;</code> needs key-based SSH to the remote backend host.</p></li><li><p>No GitHub authentication: the repo is public and releases download from fixed URLs.</p></li><li><p>A home directory on NFS (or another remote filesystem) needs a systemd drop-in pointing the daemon&#39;s state root at local disk before sessions will start; see <a href="/ship-of-tools/dev/guide/troubleshooting#A-session-will-not-start-on-a-shared-home">A session will not start on a shared home</a>.</p></li></ul><p>On <strong>Windows</strong> there is no <code>install.ps1</code> yet (<code>scripts/install.sh</code> exits with a Windows-specific message), but no Rust toolchain is needed: the release ships <code>sot-&lt;ver&gt;-windows-x86_64.zip</code>. Extract <code>sot.exe</code> into <code>%LOCALAPPDATA%\\sot\\bin</code>, clone the repo for the launcher scripts and config, and wire the shortcut with <code>scripts\\install-shortcut.ps1</code>, which points the desktop shortcut (and any taskbar pin) at <code>scripts\\launch-sot.ps1</code>. Do not point a shortcut at bare <code>sot.exe</code>, which skips the launcher&#39;s update and relaunch handling. The step-by-step walkthrough is <a href="https://github.com/kalidke/ship-of-tools/blob/main/docs/INSTALL-AGENT.md" target="_blank" rel="noreferrer">INSTALL-AGENT.md §2b</a> (written for a coding agent, equally followable by hand).</p><p>On <strong>macOS aarch64</strong> the bash installer works, but there is no launchd service; local roles start <code>sotd</code> on demand. See <a href="/ship-of-tools/dev/start/install#platforms">Platforms</a> for what is and is not supported on a Mac.</p><h2 id="install-source" tabindex="-1">From source <a class="header-anchor" href="#install-source" aria-label="Permalink to &quot;From source {#install-source}&quot;">​</a></h2><p>Ship of Tools is a Rust and Julia project: the frontend and backend are Rust binaries, the kernel and plugins are Julia. Installing from source means building the Rust workspace once and instantiating a handful of Julia environments. Machine-specific config and launchers are covered by <a href="./setup">Per-machine setup</a>; run that page&#39;s checklist by hand or let the <code>/sot-setup</code> Claude Code skill drive it.</p><h3 id="Prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#Prerequisites" aria-label="Permalink to &quot;Prerequisites {#Prerequisites}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Tool</th><th style="text-align:right;">Version</th><th style="text-align:right;">Why</th></tr></thead><tbody><tr><td style="text-align:right;">Rust toolchain</td><td style="text-align:right;">current stable</td><td style="text-align:right;">frontend, backend, protocol crates</td></tr><tr><td style="text-align:right;">Julia</td><td style="text-align:right;">1.12 or newer</td><td style="text-align:right;">kernel, <code>ConceptExplorerCore</code>, plugins</td></tr><tr><td style="text-align:right;"><code>git</code></td><td style="text-align:right;">any</td><td style="text-align:right;">clone the repo</td></tr></tbody></table><p>Install Rust with <a href="https://rustup.rs/" target="_blank" rel="noreferrer">rustup</a> and Julia with <a href="https://github.com/JuliaLang/juliaup" target="_blank" rel="noreferrer">juliaup</a>.</p><h3 id="Clone" tabindex="-1">Clone <a class="header-anchor" href="#Clone" aria-label="Permalink to &quot;Clone {#Clone}&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/kalidke/ship-of-tools</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ship-of-tools</span></span></code></pre></div><h3 id="Build-the-Rust-workspace" tabindex="-1">Build the Rust workspace <a class="header-anchor" href="#Build-the-Rust-workspace" aria-label="Permalink to &quot;Build the Rust workspace {#Build-the-Rust-workspace}&quot;">​</a></h3><p>The Rust workspace lives under <code>rust/</code> and has six members: <code>protocol</code> (shared line-protocol types), <code>backend</code> (the daemon), <code>frontend</code> (the native window), <code>updater</code>, <code>log</code> and <code>vt100</code> (a terminal-emulator fork). One command builds all of them:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --manifest-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust/Cargo.toml</span></span></code></pre></div><p>This produces the binaries the launcher runs:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Binary</th><th style="text-align:right;">Path</th><th style="text-align:right;">Role</th></tr></thead><tbody><tr><td style="text-align:right;"><code>sot</code></td><td style="text-align:right;"><code>rust/target/release/</code></td><td style="text-align:right;">native window, chrome, previews</td></tr><tr><td style="text-align:right;"><code>sotd</code></td><td style="text-align:right;"><code>rust/target/release/</code></td><td style="text-align:right;">project state, supervision, agent sessions</td></tr><tr><td style="text-align:right;"><code>sot-capsule</code></td><td style="text-align:right;"><code>rust/target/release/</code></td><td style="text-align:right;"><code>sotd</code>&#39;s capsule-runtime pair, one per session</td></tr></tbody></table><p>The first release build compiles the full rendering stack (<code>winit</code>, <code>wgpu</code>, <code>cosmic-text</code>, <code>glyphon</code>, <code>resvg</code>) and takes a while; later builds are incremental.</p><h3 id="Instantiate-the-Julia-environments" tabindex="-1">Instantiate the Julia environments <a class="header-anchor" href="#Instantiate-the-Julia-environments" aria-label="Permalink to &quot;Instantiate the Julia environments {#Instantiate-the-Julia-environments}&quot;">​</a></h3><p>The repo is a set of nested Julia environments. The umbrella environment at the repo root pins project-level dependencies such as <code>CairoMakie</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.instantiate()&#39;</span></span></code></pre></div><p>Then the core library, kernel, REPL shim, and Pluto sidecar:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">            -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.instantiate()&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=julia/kernel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.instantiate()&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=julia/repl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.instantiate()&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=julia/pluto</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.instantiate()&#39;</span></span></code></pre></div><p><code>core/</code> is <code>ConceptExplorerCore</code>, the abstract types and dispatch contract that make up the <a href="./../extend/abi">extension ABI</a>. The standard plugins live under <code>julia/plugins/*</code>; instantiate any plugin environment you intend to load the same way, e.g.:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=julia/plugins/julia-source</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.instantiate()&#39;</span></span></code></pre></div><h3 id="Verify-the-build" tabindex="-1">Verify the build <a class="header-anchor" href="#Verify-the-build" aria-label="Permalink to &quot;Verify the build {#Verify-the-build}&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust/target/release/sot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust/target/release/sotd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust/target/release/sot-capsule</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using ConceptExplorerCore; println(&quot;core OK&quot;)&#39;</span></span></code></pre></div><h2 id="Next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#Next-steps" aria-label="Permalink to &quot;Next steps {#Next-steps}&quot;">​</a></h2><ul><li><p><a href="./quickstart">Quickstart</a> — launch and start a first agent session.</p></li><li><p><a href="./remote">Going remote</a> — a backend on a server, the window on your laptop.</p></li><li><p><a href="./setup">Per-machine setup</a> — the source-checkout checklist: toolchains, config files, comm skills, and a launcher.</p></li></ul>`,70)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
